const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let generation=0,timer;
export function stopLibrary(){generation++;clearTimeout(timer);}
export async function mountLibrary(panel,{session,api}){
 const own=++generation;
 if(session.role!=='richter'){panel.innerHTML='<h3>Die gemeinsame Richterbibliothek</h3><p>Hier berät ein lokales Sprachmodell den jeweils aktuellen Vorsitz mit Fundstellen aus dem Drama, Gesetzestexten und dem Argumentationsraster. Nach einem Rollenwechsel erhält der neue Vorsitz automatisch Zugang.</p><p>Die gemeinsamen Fakten, Rechtsgrundlagen und das Grundgesetz bleiben für alle Rollen in den übrigen Aktenreitern zugänglich.</p>';return;}
 panel.innerHTML='<h3>Mit Belegen urteilen lernen</h3><p>Die Bibliothek sucht im lokalen PDF und in der Rechtssammlung. Das Modell erklärt und stellt Prüffragen; du prüfst die Fundstellen und entscheidest selbst.</p><p id="library-state" role="status">Verbindung zur Bibliothek wird geprüft …</p><details id="library-policy"><summary>Fiktive Spielregel und Bewertungsgrundlage</summary><div id="library-rule"></div><p>Bewertet werden: klare These, passender Beleg, damaliger Wissensstand, tragfähiger Schluss, Gegenargument und Trennung der Rechtsebenen. Denkfehlerhinweise sind zu prüfende Vorschläge.</p></details><form id="library-form"><label for="library-question">Deine Frage oder ein zu prüfendes Argument</label><textarea id="library-question" rows="5" minlength="8" maxlength="2000" required placeholder="Was belegt Meisers SMS? Was wusste Koch zu diesem Zeitpunkt?"></textarea><p class="source">Nur diese Frage wird an den Rechner der Lehrperson gesendet. Keine Namen oder persönlichen Angaben. Bis zu einer Stunde für den aktuellen Vorsitz gespeichert.</p><button class="primary" id="library-ask">Bibliothek fragen</button></form><div id="library-answers" aria-live="polite"></div>';
 const find=id=>panel.querySelector('#'+id);const headers={Authorization:'Bearer '+session.token};let last='';
 async function refresh(){if(own!==generation)return;try{const data=await api('/rooms/'+session.code+'/library',{headers});if(own!==generation)return;const active=data.jobs.some(j=>['queued','working'].includes(j.state));find('library-state').textContent=data.online?'LM Studio verbunden · '+(data.computers||1)+' Bibliothekscomputer · '+data.model+(active?' · Deine Frage wird bearbeitet.':' · Bibliothek bereit.'):'LM Studio offline · Die statische Richterhilfe und Gesetzesakte sind weiterhin nutzbar.';find('library-ask').disabled=!data.online||active;
 const p=data.policy;find('library-rule').innerHTML=p?`<h4>${esc(p.title)}</h4><p>${esc(p.rule)}</p><ol>${(p.requirements||[]).map(x=>'<li>'+esc(x)+'</li>').join('')}</ol><p><b>Geltendes Recht:</b> ${esc(p.actualLaw)}</p><p class="source">Version ${esc(p.version)}</p>`:'Die zentrale Spielregel wird beim nächsten Kontakt mit der Bibliothek geladen.';
 const key=JSON.stringify(data.jobs);if(key!==last){last=key;find('library-answers').innerHTML=data.jobs.slice().reverse().map(j=>`<article class="library-answer"><h4>${esc(j.question)}</h4><p class="source">${esc(j.policy?.version||'')} · ${new Date(j.created).toLocaleTimeString('de-CH')}</p><div class="library-text">${esc(j.answer||(j.state==='working'?'Das lokale Modell formuliert die Antwort …':'In der Warteschlange …'))}</div>${(j.sources||[]).map(s=>`<details><summary>[${esc(s.id)}] ${esc(s.label)}</summary><p>${esc(s.excerpt)}</p>${s.url&&/^https:\/\/(www\.)?(gesetze-im-internet\.de|bundesverfassungsgericht\.de)\//.test(s.url)?`<a href="${esc(s.url)}" target="_blank" rel="noopener">Originalquelle ↗</a>`:s.kind==='PDF'?'<a href="../#lektuere" target="_blank" rel="noopener">PDF im Leseraum öffnen ↗</a>':''}</details>`).join('')}<p class="source">KI-Beratung kann irren. Quellenkennungen wurden gegen die gefundenen Dokumente geprüft; die inhaltliche Schlussfolgerung musst du kontrollieren.</p></article>`).join('');}
 }catch(e){if(own===generation)find('library-state').textContent=e.message;}finally{if(own===generation)timer=setTimeout(refresh,5000);}}
 find('library-form').onsubmit=async e=>{e.preventDefault();find('library-ask').disabled=true;try{await api('/rooms/'+session.code+'/library',{method:'POST',headers,body:JSON.stringify({question:find('library-question').value})});clearTimeout(timer);await refresh();}catch(e){if(own===generation){find('library-state').textContent=e.message;find('library-ask').disabled=false;}}};await refresh();
}
